@Test
public void testParseSQLOutput() {
    // Empty sql output
    //    +---+---+
    //    |  a|  b|
    //    +---+---+
    //    +---+---+
    List<String> rows = sqlInterpreter.parseSQLOutput("+---+---+\n" + "|  a|  b|\n" + "+---+---+\n" + "+---+---+");
    assertEquals(1, rows.size());
    assertEquals("a\tb", rows.get(0));
    //  sql output with 2 rows
    //    +---+---+
    //    |  a|  b|
    //    +---+---+
    //    |  1| 1a|
    //    |  2| 2b|
    //    +---+---+
    rows = sqlInterpreter.parseSQLOutput("+---+---+\n" + "|  a|  b|\n" + "+---+---+\n" + "|  1| 你|\n" + "|  2| 2b|\n" + "+---+---+");
    assertEquals(3, rows.size());
    assertEquals("a\tb", rows.get(0));
    assertEquals("1\t你", rows.get(1));
    assertEquals("2\t2b", rows.get(2));
    //  sql output with 3 rows and showing "only showing top 3 rows"
    //    +---+---+
    //    |  a|  b|
    //    +---+---+
    //    |  1| 1a|
    //    |  2| 2b|
    //    |  3| 3c|
    //    +---+---+
    //    only showing top 3 rows
    rows = sqlInterpreter.parseSQLOutput("+---+---+\n" + "|  a|  b|\n" + "+---+---+\n" + "|  1| 1a|\n" + "|  2| 2b|\n" + "|  3| 3c|\n" + "+---+---+\n" + "only showing top 3 rows");
    assertEquals(4, rows.size());
    assertEquals("a\tb", rows.get(0));
    assertEquals("1\t1a", rows.get(1));
    assertEquals("2\t2b", rows.get(2));
    assertEquals("3\t3c", rows.get(3));
    //  sql output with 1 rows and showing "only showing top 1 rows"
    //    +---+
    //    |  a|
    //    +---+
    //    |  1|
    //    +---+
    //    only showing top 1 rows
    rows = sqlInterpreter.parseSQLOutput("+---+\n" + "|  a|\n" + "+---+\n" + "|  1|\n" + "+---+\n" + "only showing top 1 rows");
    assertEquals(2, rows.size());
    assertEquals("a", rows.get(0));
    assertEquals("1", rows.get(1));
    //  sql output with 3 rows, 3 columns, showing "only showing top 3 rows" with a line break in
    //  the data
    //    +---+---+---+
    //    |  a|  b|  c|
    //    +---+---+---+
    //    | 1a| 1b| 1c|
    //    | 2a| 2
    //    b| 2c|
    //    | 3a| 3b| 3c|
    //    +---+---+---+
    //    only showing top 3 rows
    rows = sqlInterpreter.parseSQLOutput("+---+----+---+\n" + "|  a|   b|  c|\n" + "+---+----+---+\n" + "| 1a|  1b| 1c|\n" + "| 2a| 2\nb| 2c|\n" + "| 3a|  3b| 3c|\n" + "+---+---+---+\n" + "only showing top 3 rows");
    assertEquals(4, rows.size());
    assertEquals("a\tb\tc", rows.get(0));
    assertEquals("1a\t1b\t1c", rows.get(1));
    assertEquals("2a\t2\\nb\t2c", rows.get(2));
    assertEquals("3a\t3b\t3c", rows.get(3));
    //  sql output with 2 rows and one containing a tab
    //    +---+---+
    //    |  a|  b|
    //    +---+---+
    //    |  1| \ta|
    //    |  2| 2b|
    //    +---+---+
    rows = sqlInterpreter.parseSQLOutput("+---+---+\n" + "|  a|  b|\n" + "+---+---+\n" + "|  1| \ta|\n" + "|  2| 2b|\n" + "+---+---+");
    assertEquals(3, rows.size());
    assertEquals("a\tb", rows.get(0));
    assertEquals("1\t\\ta", rows.get(1));
    assertEquals("2\t2b", rows.get(2));
}

@Test
public void parseSQLJsonOutput() {
    //  Empty sql output
    //  id name
    List<String> rows = sqlInterpreter.parseSQLJsonOutput("\nid\tname\n");
    assertEquals(1, rows.size());
    assertEquals("id\tname", rows.get(0));
    //  sql output with 2 rows
    //  id name
    //  {"id":1,"name":"1a"}
    //  {"id":2,"name":"2a"}
    rows = sqlInterpreter.parseSQLJsonOutput("\nid\tname\n" + "{\"id\":1,\"name\":\"1a\"}\n" + "{\"id\":2,\"name\":\"2a\"}");
    assertEquals(3, rows.size());
    assertEquals("id\tname", rows.get(0));
    assertEquals("1\t1a", rows.get(1));
    assertEquals("2\t2a", rows.get(2));
    //  sql output with 3 rows and showing "only showing top 3 rows"
    //  id\tname
    //  {"id":1,"name":"1a"}
    //  {"id":2,"name":"2a"}
    //  {"id":3,"name":"3a"}
    //  only showing top 3 rows
    rows = sqlInterpreter.parseSQLJsonOutput("\nid\tname\n" + "{\"id\":1,\"name\":\"1a\"}\n" + "{\"id\":2,\"name\":\"2a\"}\n" + "{\"id\":3,\"name\":\"3a\"}");
    assertEquals(4, rows.size());
    assertEquals("id\tname", rows.get(0));
    assertEquals("1\t1a", rows.get(1));
    assertEquals("2\t2a", rows.get(2));
    assertEquals("3\t3a", rows.get(3));
    //  sql output with 1 rows and showing "only showing top 1 rows"
    //  id
    //  {"id":1}
    //  {"id":2}
    //  {"id":3}
    //  only showing top 1 rows
    rows = sqlInterpreter.parseSQLJsonOutput("\nid\n" + "{\"id\":1}");
    assertEquals(2, rows.size());
    assertEquals("id", rows.get(0));
    assertEquals("1", rows.get(1));
    //  sql output with 3 rows, 3 columns, showing "only showing top 3 rows" with a line break in
    //  the data
    //  id name destination
    //  {"id":1,"name":"1a","destination":"1b"}
    //  {"id":2,"name":"2\na","destination":"2b"}
    //  {"id":3,"name":"3a","destination":"3b"}
    //  only showing top 3 rows
    rows = sqlInterpreter.parseSQLJsonOutput("\nid\tname\tdestination\n" + "{\"id\":1,\"name\":\"1a\",\"destination\":\"1b\"}\n" + "{\"id\":2,\"name\":\"2\\na\",\"destination\":\"2b\"}\n" + "{\"id\":3,\"name\":\"3a\",\"destination\":\"3b\"}");
    assertEquals(4, rows.size());
    assertEquals("id\tname\tdestination", rows.get(0));
    assertEquals("1\t1a\t1b", rows.get(1));
    assertEquals("2\t2\\na\t2b", rows.get(2));
    assertEquals("3\t3a\t3b", rows.get(3));
    //  sql output with 3 rows and one containing a tab
    //  id name
    //  {"id":1,"name":"1a"}
    //  {"id":2,"name":"2\ta"}
    //  {"id":3,"name":"3a"}
    //  only showing top 3 rows
    rows = sqlInterpreter.parseSQLJsonOutput("\nid\tname\n" + "{\"id\":1,\"name\":\"1a\"}\n" + "{\"id\":2,\"name\":\"2\ta\"}\n" + "{\"id\":3,\"name\":\"3a\"}");
    assertEquals(4, rows.size());
    assertEquals("id\tname", rows.get(0));
    assertEquals("1\t1a", rows.get(1));
    assertEquals("2\t2\\ta", rows.get(2));
    assertEquals("3\t3a", rows.get(3));
    //  sql output with 3 rows and one containing a Japanese characters
    //  id name
    //  {"id":1,"name":"1a"}
    //  {"id":2,"name":"みんく"}
    //  {"id":3,"name":"3a"}
    //  only showing top 3 rows
    rows = sqlInterpreter.parseSQLJsonOutput("\nid\tname\n" + "{\"id\":1,\"name\":\"1a\"}\n" + "{\"id\":2,\"name\":\"みんく\"}\n" + "{\"id\":3,\"name\":\"3a\"}");
    assertEquals(4, rows.size());
    assertEquals("id\tname", rows.get(0));
    assertEquals("1\t1a", rows.get(1));
    assertEquals("2\tみんく", rows.get(2));
    assertEquals("3\t3a", rows.get(3));
}

@Test
public void testMultipleThread() {
    ArrayList<Thread> arrThreads = new ArrayList<Thread>();
    for (int i = 0; i < 10; i++) {
        Thread t = new Thread() {

            @Override
            public void run() {
                String r1 = null;
                try {
                    r1 = md.interpret("# H1", null).code().name();
                } catch (Exception e) {
                    LOGGER.error("testTestMultipleThread failed to interpret", e);
                }
                collector.checkThat("SUCCESS", CoreMatchers.containsString(r1));
            }
        };
        t.start();
        arrThreads.add(t);
    }
    for (int i = 0; i < 10; i++) {
        try {
            arrThreads.get(i).join();
        } catch (InterruptedException e) {
            LOGGER.error("testTestMultipleThread failed to join threads", e);
        }
    }
}

