    p.setProperty(Neo4jCypherInterpreter.NEO4J_MULTI_STATEMENT, "true");
    Neo4jCypherInterpreter multiLineInterpreter = new Neo4jCypherInterpreter(p);
    context = InterpreterContext.builder().setInterpreterOut(new InterpreterOutput()).build();
    InterpreterResult result = multiLineInterpreter.interpret("CREATE (n:Node{name: ';'});" + "\nRETURN 1 AS val;", context);
    assertEquals(Code.SUCCESS, result.code());
    assertEquals("val\n1\n", result.toString().replace(TABLE_RESULT_PREFIX, StringUtils.EMPTY));
    result = multiLineInterpreter.interpret("CREATE (n:Node{name: \";\"}); " + "RETURN 2 AS `other;Val`;", context);
    assertEquals(Code.SUCCESS, result.code());
    assertEquals("other;Val\n2\n", result.toString().replace(TABLE_RESULT_PREFIX, StringUtils.EMPTY));
    result = multiLineInterpreter.interpret("match (n:Node{name: ';'}) " + "return count(n) AS count", context);
    assertEquals("count\n2\n", result.toString().replace(TABLE_RESULT_PREFIX, StringUtils.EMPTY));
    result = multiLineInterpreter.interpret("match (n:Node) detach delete n; " + "match (n:Node) return count(n) AS count", context);
    assertEquals("count\n0\n", result.toString().replace(TABLE_RESULT_PREFIX, StringUtils.EMPTY));
}

