@Test
public void testHooks() throws InvalidHookException {
    InterpreterHookRegistry hookRegistry = new InterpreterHookRegistry();
    TestZeppelinContext z = new TestZeppelinContext(hookRegistry, 10);
    InterpreterContext context = InterpreterContext.builder().setNoteId("note_1").setNoteName("note_name_1").setParagraphId("paragraph_1").setInterpreterClassName("Test1Interpreter").setReplName("test1").build();
    z.setInterpreterContext(context);
    // get note name via InterpreterContext
    String note_name = z.getInterpreterContext().getNoteName();
    assertEquals(String.format("Actual note name: %s, but expected %s", note_name, "note_name_1"), "note_name_1", note_name);
    // register global hook for current interpreter
    z.registerHook(InterpreterHookRegistry.HookType.PRE_EXEC.getName(), "pre_cmd");
    z.registerHook(InterpreterHookRegistry.HookType.POST_EXEC.getName(), "post_cmd");
    assertEquals("pre_cmd", hookRegistry.get(null, "Test1Interpreter", InterpreterHookRegistry.HookType.PRE_EXEC.getName()));
    assertEquals("post_cmd", hookRegistry.get(null, "Test1Interpreter", InterpreterHookRegistry.HookType.POST_EXEC.getName()));
    z.unregisterHook(InterpreterHookRegistry.HookType.PRE_EXEC.getName());
    z.unregisterHook(InterpreterHookRegistry.HookType.POST_EXEC.getName());
    assertEquals(null, hookRegistry.get(null, "Test1Interpreter", InterpreterHookRegistry.HookType.PRE_EXEC.getName()));
    assertEquals(null, hookRegistry.get(null, "Test1Interpreter", InterpreterHookRegistry.HookType.POST_EXEC.getName()));
    // register global hook for interpreter test2
    z.registerHook(InterpreterHookRegistry.HookType.PRE_EXEC.getName(), "pre_cmd2", "test2");
    z.registerHook(InterpreterHookRegistry.HookType.POST_EXEC.getName(), "post_cmd2", "test2");
    assertEquals("pre_cmd2", hookRegistry.get(null, "Test2Interpreter", InterpreterHookRegistry.HookType.PRE_EXEC.getName()));
    assertEquals("post_cmd2", hookRegistry.get(null, "Test2Interpreter", InterpreterHookRegistry.HookType.POST_EXEC.getName()));
    z.unregisterHook(InterpreterHookRegistry.HookType.PRE_EXEC.getName(), "test2");
    z.unregisterHook(InterpreterHookRegistry.HookType.POST_EXEC.getName(), "test2");
    assertEquals(null, hookRegistry.get(null, "Test2Interpreter", InterpreterHookRegistry.HookType.PRE_EXEC.getName()));
    assertEquals(null, hookRegistry.get(null, "Test2Interpreter", InterpreterHookRegistry.HookType.POST_EXEC.getName()));
    // register hook for note_1 and current interpreter
    z.registerNoteHook(InterpreterHookRegistry.HookType.PRE_EXEC.getName(), "pre_cmd", "note_1");
    z.registerNoteHook(InterpreterHookRegistry.HookType.POST_EXEC.getName(), "post_cmd", "note_1");
    assertEquals("pre_cmd", hookRegistry.get("note_1", "Test1Interpreter", InterpreterHookRegistry.HookType.PRE_EXEC.getName()));
    assertEquals("post_cmd", hookRegistry.get("note_1", "Test1Interpreter", InterpreterHookRegistry.HookType.POST_EXEC.getName()));
    z.unregisterNoteHook("note_1", InterpreterHookRegistry.HookType.PRE_EXEC.getName(), "test1");
    z.unregisterNoteHook("note_1", InterpreterHookRegistry.HookType.POST_EXEC.getName(), "test1");
    assertEquals(null, hookRegistry.get("note_1", "Test1Interpreter", InterpreterHookRegistry.HookType.PRE_EXEC.getName()));
    assertEquals(null, hookRegistry.get("note_1", "Test1Interpreter", InterpreterHookRegistry.HookType.POST_EXEC.getName()));
    // register hook for note_1 and interpreter test2
    z.registerNoteHook(InterpreterHookRegistry.HookType.PRE_EXEC.getName(), "pre_cmd2", "note_1", "test2");
    z.registerNoteHook(InterpreterHookRegistry.HookType.POST_EXEC.getName(), "post_cmd2", "note_1", "test2");
    assertEquals("pre_cmd2", hookRegistry.get("note_1", "Test2Interpreter", InterpreterHookRegistry.HookType.PRE_EXEC.getName()));
    assertEquals("post_cmd2", hookRegistry.get("note_1", "Test2Interpreter", InterpreterHookRegistry.HookType.POST_EXEC.getName()));
    z.unregisterNoteHook("note_1", InterpreterHookRegistry.HookType.PRE_EXEC.getName(), "test2");
    z.unregisterNoteHook("note_1", InterpreterHookRegistry.HookType.POST_EXEC.getName(), "test2");
    assertEquals(null, hookRegistry.get("note_1", "Test2Interpreter", InterpreterHookRegistry.HookType.PRE_EXEC.getName()));
    assertEquals(null, hookRegistry.get("note_1", "Test2Interpreter", InterpreterHookRegistry.HookType.POST_EXEC.getName()));
}

