@Test
public void testK8sStartTimeoutPending() throws InterruptedException {
    // given
    Properties properties = new Properties();
    Map<String, String> envs = new HashMap<>();
    envs.put("SERVICE_DOMAIN", "mydomain");
    URL url = Thread.currentThread().getContextClassLoader().getResource("k8s-specs/interpreter-spec.yaml");
    File file = new File(url.getPath());
    K8sRemoteInterpreterProcess intp = new K8sRemoteInterpreterProcess(server.getClient(), "default", file, "interpreter-container:1.0", "shared_process", "spark", "myspark", properties, envs, "zeppelin.server.service", 12320, false, "spark-container:1.0", 3000, 10, false, false);
    PodStatusSimulator podStatusSimulator = new PodStatusSimulator(server.getClient(), intp.getInterpreterNamespace(), intp.getPodName(), intp);
    podStatusSimulator.setFirstPhase("Pending");
    podStatusSimulator.setSecondPhase("Pending");
    podStatusSimulator.setSuccessfulStart(false);
    ExecutorService service = Executors.newFixedThreadPool(2);
    service.submit(podStatusSimulator);
    service.submit(() -> {
        try {
            intp.start("TestUser");
            fail("We interrupt, this line of code should not be executed.");
        } catch (IOException e) {
            fail("We interrupt, this line of code should not be executed.");
        }
    });
    // wait a little bit
    TimeUnit.SECONDS.sleep(5);
    service.shutdownNow();
    // wait for a shutdown
    service.awaitTermination(10, TimeUnit.SECONDS);
    // Check that the Pod is deleted
    assertNull(server.getClient().pods().inNamespace(intp.getInterpreterNamespace()).withName(intp.getPodName()).get());
}

