    notebook.processNote(note2Id, note2 -> {
        verify(callback).onSuccess(note2, context);
        assertEquals("new_note2", note2.getName());
        return null;
    });
    // list note
    reset(callback);
    notesInfo = notebookService.listNotesInfo(false, context, callback);
