@Test
public void testSyncUpdateMain() throws IOException {
    /* create note */
    String noteId = notebook.createNote("/test", "test", anonymous);
    notebook.processNote(noteId, note -> {
        note.setInterpreterFactory(mock(InterpreterFactory.class));
        Paragraph p1 = note.addNewParagraph(AuthenticationInfo.ANONYMOUS);
        Map config = p1.getConfig();
        config.put("enabled", true);
        p1.setConfig(config);
        p1.setText("hello world");
        /* new paragraph exists in note instance */
        assertEquals(1, note.getParagraphs().size());
        return null;
    });
    /* new paragraph not yet saved into storages */
    assertEquals(0, notebookRepoSync.get(0, notebookRepoSync.list(0, anonymous).get(0).getId(), notebookRepoSync.list(0, anonymous).get(0).getPath(), anonymous).getParagraphs().size());
    assertEquals(0, notebookRepoSync.get(1, notebookRepoSync.list(1, anonymous).get(0).getId(), notebookRepoSync.list(1, anonymous).get(0).getPath(), anonymous).getParagraphs().size());
    /* save to storage under index 0 (first storage) */
    notebook.processNote(noteId, note -> {
        notebookRepoSync.save(0, note, anonymous);
        return null;
    });
    /* check paragraph saved to first storage */
    assertEquals(1, notebookRepoSync.get(0, notebookRepoSync.list(0, anonymous).get(0).getId(), notebookRepoSync.list(0, anonymous).get(0).getPath(), anonymous).getParagraphs().size());
    /* check paragraph isn't saved to second storage */
    assertEquals(0, notebookRepoSync.get(1, notebookRepoSync.list(1, anonymous).get(0).getId(), notebookRepoSync.list(0, anonymous).get(0).getPath(), anonymous).getParagraphs().size());
    /* apply sync */
    notebookRepoSync.sync(null);
    /* check whether added to second storage */
    assertEquals(1, notebookRepoSync.get(1, notebookRepoSync.list(1, anonymous).get(0).getId(), notebookRepoSync.list(1, anonymous).get(0).getPath(), anonymous).getParagraphs().size());
    /* check whether same paragraph id */
    notebook.processNote(noteId, note -> {
        Paragraph p1 = note.getParagraph(0);
        assertEquals(p1.getId(), notebookRepoSync.get(0, notebookRepoSync.list(0, anonymous).get(0).getId(), notebookRepoSync.list(0, anonymous).get(0).getPath(), anonymous).getLastParagraph().getId());
        assertEquals(p1.getId(), notebookRepoSync.get(1, notebookRepoSync.list(1, anonymous).get(0).getId(), notebookRepoSync.list(1, anonymous).get(0).getPath(), anonymous).getLastParagraph().getId());
        notebookRepoSync.remove(note.getId(), note.getPath(), anonymous);
        return null;
    });
}

