    assertEquals("", gson.fromJson(intp1.interpret("get note1:paragraph2:key1", context).message().get(0).getData(), String.class));
    // when remove all resources from note2:paragraph1
    interpreterSettingManager.removeResourcesBelongsToParagraph(note2Id, "paragraph1");
    // then 1
    assertEquals(1, interpreterSettingManager.getAllResources().size());
    assertEquals("value2", gson.fromJson(intp1.interpret("get " + note2Id + ":paragraph2:key2", context).message().get(0).getData(), String.class));
